    def generate_k_cnf(k, n):
        clauses = []
        for _ in range(n * k):
            clause = set()
            while len(clause) < k:
                var = random.randint(1, 2*n)
                if var not in clause:
                    clause.add(var)
            clauses.append(tuple(sorted(clause)))
        return clauses

    def rank_eilenberg_mac_lane_space(k, n):
